    {
      "id": "check",
      "concept_ids": [
        "m6.health-promotion",
        "m6.family-planning",
        "m6.distress",
        "m6.smoking"
      ],
      "asset_ids": [
        "explain-check"
      ],
      "takeaway_fil": "Kapag iba ang pagkaunawa, ayusin ang sariling paliwanag at mag-check muli. Hindi kasalanan ng kausap ang hindi malinaw na mensahe.",
      "takeaway_en": "When understanding differs, repair your explanation and check again. An unclear message is not the person’s fault.",
      "check": {
        "prompt_fil": "Sa teach-back, iba ang planong ikinuwento ni Liza. Ano ang susunod?",
        "prompt_en": "During teach-back, Liza describes a different plan. What next?",
        "options": [
          {
            "fil": "Sabihing mali at tapusin ang usapan.",
            "en": "Say it is wrong and end the conversation."
          },
          {
            "fil": "Ibigay ang parehong paliwanag nang mas mabilis.",
            "en": "Give the same explanation more quickly."
          },
          {
            "fil": "Ipaliwanag sa ibang paraan at ipasabi muli ang hakbang.",
            "en": "Explain another way and ask her to describe the step again."
          }
        ],
        "correct_option_index": 2,
        "feedback_fil": "Una: Ang pagsisi at pagtatapos ay hindi nag-aayos ng hindi malinaw na mensahe at maaaring magpatahimik kay Liza. Ikalawa: Ang parehong paliwanag nang mas mabilis ay hindi tumutugon sa maling pagkaunawa. Ikatlo: Ang ibang paraan ng paliwanag at pag-check muli ay angkop; si Gibs ang may pananagutan sa linaw. Sa wakas, sabi ni Gibs, “Hindi pa appointment. Magtatanong muna tayo tungkol sa iskedyul. Ano muna ang gagawin natin?” Sagot ni Liza, “Magtatanong tungkol sa iskedyul; wala pang kumpirmadong appointment.” “Tama, iyon muna,” tugon ni Gibs.",
        "feedback_en": "First: Blame and ending the conversation do not repair an unclear message and may silence Liza. Second: The same explanation delivered faster does not address the misunderstanding. Third: Explaining another way and checking again is appropriate; Gibs takes responsibility for clarity. In the ending, Gibs says, “This is not an appointment yet. We will ask about scheduling first. What will we do first?” Liza replies, “Ask about the schedule; there is no confirmed appointment.” “Yes, that is the first step,” Gibs confirms."
      }
    }
  ],
